fn escape_json(s: String) String -> {
    result := ""
    loop ch in s.chars() {
        if ch == '"' -> result += "\\\""
        else if ch == '\\' -> result += "\\\\"
        else if ch == '\n' -> result += "\\n"
        else if ch == '\t' -> result += "\\t"
        else -> result += "{ch}"
    }
    return result
}

